import { test, expect } from '@playwright/test';
import { supabaseSession, teamChangeHistory, TEST_COMPANY_ID } from './audit-helpers';

test.use({ storageState: '../auth/user.json' });

test.describe('Audit log — RLS для не супер-админа (#fc4fa4)', () => {
  test('team_change_history for another company returns no records to a regular user #fc4fa4 @desktop @prod-safe', async ({ page }) => {
    const s = await supabaseSession(page);
    const { status, body } = await teamChangeHistory(page, s, TEST_COMPANY_ID);
    expect(status, 'POST /rest/v1/rpc/team_change_history').toBe(200);
    expect(body, 'история чужой команды не отдаётся').toEqual([]);
  });
});
